export interface Frontmatter {
  title: string;
  date?: string;
  tags?: string[];
}

export interface Page {
  frontmatter: Frontmatter;
  content: string;
  html: string;
  slug: string;
  sourcePath: string;
}

import fs from 'fs';
import path from 'path';
import matter from 'gray-matter';
import { marked } from 'marked';
import { Page, Frontmatter } from './types';

export function parseMarkdownFile(filePath: string): Page {
  const raw = fs.readFileSync(filePath, 'utf-8');
  const parsed = matter(raw);
  const frontmatter = parsed.data as Frontmatter;

  if (!frontmatter.title) {
    throw new Error(`Missing required frontmatter field "title" in ${filePath}`);
  }

  const html = marked.parse(parsed.content) as string;
  const slug = path.basename(filePath, path.extname(filePath));

  return {
    frontmatter,
    content: parsed.content,
    html,
    slug,
    sourcePath: filePath,
  };
}

export function parseMarkdownDirectory(
  contentDir: string,
): Page[] {
  if (!fs.existsSync(contentDir)) {
    throw new Error(`Content directory not found: ${contentDir}`);
  }

  const entries = fs.readdirSync(contentDir);
  const pages: Page[] = [];

  for (const entry of entries) {
    const fullPath = path.join(contentDir, entry);
    const stat = fs.statSync(fullPath);
    if (stat.isFile() && (entry.endsWith('.md') || entry.endsWith('.markdown'))) {
      pages.push(parseMarkdownFile(fullPath));
    }
  }

  return pages.sort((a, b) => {
    const dateA = a.frontmatter.date || '';
    const dateB = b.frontmatter.date || '';
    return dateB.localeCompare(dateA);
  });
}

import { Page } from './types';

function escapeHtml(text: string): string {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

export function generatePageHtml(page: Page): string {
  const { title, date, tags } = page.frontmatter;
  const dateStr = date || '';
  const tagsStr = tags ? tags.map((t) => escapeHtml(t)).join(', ') : '';

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${escapeHtml(title)}</title>
</head>
<body>
  <header>
    <nav><a href="index.html">Home</a></nav>
  </header>
  <main>
    <article>
      <h1>${escapeHtml(title)}</h1>
      ${dateStr ? `<time datetime="${escapeHtml(dateStr)}">${escapeHtml(dateStr)}</time>` : ''}
      ${tagsStr ? `<p>Tags: ${tagsStr}</p>` : ''}
      <div>${page.html}</div>
    </article>
  </main>
</body>
</html>`;
}

export function generateIndexHtml(pages: Page[]): string {
  const items = pages
    .map((page) => {
      const { title, date, tags } = page.frontmatter;
      const dateStr = date || '';
      const tagsStr = tags ? tags.map((t) => escapeHtml(t)).join(', ') : '';

      return `      <li>
        <a href="${escapeHtml(page.slug)}.html">${escapeHtml(title)}</a>
        ${dateStr ? `<span>${escapeHtml(dateStr)}</span>` : ''}
        ${tagsStr ? `<span>Tags: ${tagsStr}</span>` : ''}
      </li>`;
    })
    .join('\n');

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Index</title>
</head>
<body>
  <header>
    <h1>All Pages</h1>
  </header>
  <main>
    <ul>
${items}
    </ul>
  </main>
</body>
</html>`;
}

import fs from 'fs';
import path from 'path';
import { parseMarkdownDirectory } from './parser';
import { generatePageHtml, generateIndexHtml } from './generator';

export interface BuildOptions {
  contentDir: string;
  outputDir: string;
}

export function build(options: BuildOptions): void {
  const { contentDir, outputDir } = options;

  const pages = parseMarkdownDirectory(contentDir);

  fs.mkdirSync(outputDir, { recursive: true });

  for (const page of pages) {
    const html = generatePageHtml(page);
    const outPath = path.join(outputDir, `${page.slug}.html`);
    fs.writeFileSync(outPath, html, 'utf-8');
  }

  const indexHtml = generateIndexHtml(pages);
  const indexPath = path.join(outputDir, 'index.html');
  fs.writeFileSync(indexPath, indexHtml, 'utf-8');
}

#!/usr/bin/env node
import { Command } from 'commander';
import path from 'path';
import { build } from './build';

const program = new Command();

program
  .name('ssg')
  .description('A static site generator')
  .version('1.0.0');

program
  .command('build')
  .description('Build the static site')
  .option('--content <dir>', 'Content directory', './content')
  .option('--output <dir>', 'Output directory', './dist')
  .action((options) => {
    const contentDir = path.resolve(options.content);
    const outputDir = path.resolve(options.output);
    build({ contentDir, outputDir });
  });

program.parse(process.argv);

