import { parseMarkdownFile, parseMarkdownDirectory } from '../src/parser';
import fs from 'fs';
import path from 'path';

const testContentDir = path.join(__dirname, 'content');

function createTestContent(filename: string, content: string) {
  fs.mkdirSync(testContentDir, { recursive: true });
  fs.writeFileSync(path.join(testContentDir, filename), content, 'utf-8');
}

function cleanupTestContent() {
  if (fs.existsSync(testContentDir)) {
    fs.rmSync(testContentDir, { recursive: true, force: true });
  }
}

beforeEach(() => {
  cleanupTestContent();
  fs.mkdirSync(testContentDir, { recursive: true });
});

afterEach(() => {
  cleanupTestContent();
});

describe('parseMarkdownFile', () => {
  it('parses markdown with frontmatter correctly', () => {
    const md = `---
title: Hello World
date: 2024-01-15
tags:
  - javascript
  - ssg
---
# Heading

This is a paragraph.`;

    const filePath = path.join(testContentDir, 'hello.md');
    fs.writeFileSync(filePath, md, 'utf-8');

    const page = parseMarkdownFile(filePath);

    expect(page.frontmatter.title).toBe('Hello World');
    expect(page.frontmatter.date).toBe('2024-01-15');
    expect(page.frontmatter.tags).toEqual(['javascript', 'ssg']);
    expect(page.slug).toBe('hello');
    expect(page.html).toContain('<h1>Heading</h1>');
    expect(page.html).toContain('<p>This is a paragraph.</p>');
  });

  it('parses markdown without optional frontmatter fields', () => {
    const md = `---
title: Minimal
---
Just content.`;

    const filePath = path.join(testContentDir, 'minimal.md');
    fs.writeFileSync(filePath, md, 'utf-8');

    const page = parseMarkdownFile(filePath);

    expect(page.frontmatter.title).toBe('Minimal');
    expect(page.frontmatter.date).toBeUndefined();
    expect(page.frontmatter.tags).toBeUndefined();
    expect(page.slug).toBe('minimal');
  });

  it('throws on missing title', () => {
    const md = `---
date: 2024-01-01
---
No title here`;

    const filePath = path.join(testContentDir, 'notitle.md');
    fs.writeFileSync(filePath, md, 'utf-8');

    expect(() => parseMarkdownFile(filePath)).toThrow('Missing required frontmatter field "title"');
  });

  it('handles .markdown extension', () => {
    const md = `---
title: Markdown Ext
---
Content`;

    const filePath = path.join(testContentDir, 'ext.markdown');
    fs.writeFileSync(filePath, md, 'utf-8');

    const page = parseMarkdownFile(filePath);
    expect(page.slug).toBe('ext');
  });
});

describe('parseMarkdownDirectory', () => {
  it('reads all markdown files from directory', () => {
    createTestContent(
      'first.md',
      `---
title: First
date: 2024-03-01
---
First content`,
    );
    createTestContent(
      'second.md',
      `---
title: Second
date: 2024-01-01
---
Second content`,
    );

    const pages = parseMarkdownDirectory(testContentDir);
    expect(pages).toHaveLength(2);
    expect(pages[0].frontmatter.title).toBe('First');
    expect(pages[1].frontmatter.title).toBe('Second');
  });

  it('sorts pages by date in descending order', () => {
    createTestContent(
      'a.md',
      `---
title: Old
date: 2023-01-01
---
Old content`,
    );
    createTestContent(
      'b.md',
      `---
title: New
date: 2024-12-31
---
New content`,
    );
    createTestContent(
      'c.md',
      `---
title: Mid
date: 2024-06-15
---
Mid content`,
    );

    const pages = parseMarkdownDirectory(testContentDir);
    expect(pages[0].frontmatter.title).toBe('New');
    expect(pages[1].frontmatter.title).toBe('Mid');
    expect(pages[2].frontmatter.title).toBe('Old');
  });

  it('throws on non-existent directory', () => {
    expect(() => parseMarkdownDirectory('/nonexistent/path')).toThrow(
      'Content directory not found',
    );
  });

  it('skips non-markdown files', () => {
    createTestContent('page.md', `---\ntitle: Page\n---\nContent`);
    createTestContent('readme.txt', 'not markdown');

    const pages = parseMarkdownDirectory(testContentDir);
    expect(pages).toHaveLength(1);
    expect(pages[0].slug).toBe('page');
  });
});

import { generatePageHtml, generateIndexHtml } from '../src/generator';
import { Page, Frontmatter } from '../src/types';

function makePage(
  overrides: Partial<Frontmatter> & { slug?: string; html?: string },
): Page {
  return {
    frontmatter: {
      title: 'Default Title',
      ...overrides,
    },
    content: '',
    html: overrides.html || '<p>Hello</p>',
    slug: overrides.slug || 'default',
    sourcePath: '/tmp/default.md',
  };
}

describe('generatePageHtml', () => {
  it('generates valid HTML with title', () => {
    const html = generatePageHtml(makePage({ title: 'Test Page' }));
    expect(html).toContain('<title>Test Page</title>');
    expect(html).toContain('<h1>Test Page</h1>');
    expect(html).toContain('<p>Hello</p>');
    expect(html).toContain('<!DOCTYPE html>');
  });

  it('includes date when provided', () => {
    const html = generatePageHtml(makePage({ title: 'Dated', date: '2024-05-10' }));
    expect(html).toContain('<time datetime="2024-05-10">2024-05-10</time>');
  });

  it('includes tags when provided', () => {
    const html = generatePageHtml(makePage({ title: 'Tagged', tags: ['js', 'ts'] }));
    expect(html).toContain('<p>Tags: js, ts</p>');
  });

  it('escapes HTML in title', () => {
    const html = generatePageHtml(makePage({ title: '<script>alert("xss")</script>' }));
    expect(html).toContain('&lt;script&gt;alert(&quot;xss&quot;)&lt;/script&gt;');
    expect(html).not.toContain('<script>');
  });

  it('includes link back to index', () => {
    const html = generatePageHtml(makePage({ title: 'A' }));
    expect(html).toContain('<a href="index.html">Home</a>');
  });
});

describe('generateIndexHtml', () => {
  it('generates index with all pages', () => {
    const pages = [
      makePage({ title: 'Page 1', slug: 'page1' }),
      makePage({ title: 'Page 2', slug: 'page2' }),
    ];
    const html = generateIndexHtml(pages);
    expect(html).toContain('<a href="page1.html">Page 1</a>');
    expect(html).toContain('<a href="page2.html">Page 2</a>');
    expect(html).toContain('<!DOCTYPE html>');
    expect(html).toContain('<h1>All Pages</h1>');
  });

  it('handles empty page list', () => {
    const html = generateIndexHtml([]);
    expect(html).toContain('<ul>\n\n    </ul>');
  });

  it('includes dates and tags in listing', () => {
    const pages = [
      makePage({
        title: 'A Post',
        slug: 'a-post',
        date: '2024-06-01',
        tags: ['news'],
      }),
    ];
    const html = generateIndexHtml(pages);
    expect(html).toContain('2024-06-01');
    expect(html).toContain('news');
  });

  it('escapes HTML in listing', () => {
    const pages = [makePage({ title: '<b>Bold</b>', slug: 'bold' })];
    const html = generateIndexHtml(pages);
    expect(html).toContain('&lt;b&gt;Bold&lt;/b&gt;');
    expect(html).not.toContain('<b>Bold</b>');
  });
});

import { build } from '../src/build';
import fs from 'fs';
import path from 'path';

const testBase = path.join(__dirname, 'integration');
const contentDir = path.join(testBase, 'content');
const outputDir = path.join(testBase, 'dist');

beforeEach(() => {
  if (fs.existsSync(testBase)) {
    fs.rmSync(testBase, { recursive: true, force: true });
  }
  fs.mkdirSync(contentDir, { recursive: true });
});

afterEach(() => {
  if (fs.existsSync(testBase)) {
    fs.rmSync(testBase, { recursive: true, force: true });
  }
});

describe('build', () => {
  it('generates HTML files for each markdown page', () => {
    fs.writeFileSync(
      path.join(contentDir, 'hello.md'),
      `---
title: Hello World
date: 2024-01-15
tags:
  - greeting
---
# Hello

This is a test.`,
      'utf-8',
    );

    build({ contentDir, outputDir });

    const helloPath = path.join(outputDir, 'hello.html');
    expect(fs.existsSync(helloPath)).toBe(true);

    const html = fs.readFileSync(helloPath, 'utf-8');
    expect(html).toContain('<title>Hello World</title>');
    expect(html).toContain('<h1>Hello</h1>');
    expect(html).toContain('This is a test.');
  });

  it('generates an index.html with links to all pages', () => {
    fs.writeFileSync(
      path.join(contentDir, 'alpha.md'),
      `---
title: Alpha
---
Alpha content`,
    );
    fs.writeFileSync(
      path.join(contentDir, 'beta.md'),
      `---
title: Beta
---
Beta content`,
    );

    build({ contentDir, outputDir });

    const indexPath = path.join(outputDir, 'index.html');
    expect(fs.existsSync(indexPath)).toBe(true);

    const indexHtml = fs.readFileSync(indexPath, 'utf-8');
    expect(indexHtml).toContain('<a href="alpha.html">Alpha</a>');
    expect(indexHtml).toContain('<a href="beta.html">Beta</a>');
  });

  it('creates output directory if it does not exist', () => {
    fs.writeFileSync(
      path.join(contentDir, 'page.md'),
      `---
title: Page
---
Content`,
    );

    expect(fs.existsSync(outputDir)).toBe(false);
    build({ contentDir, outputDir });
    expect(fs.existsSync(outputDir)).toBe(true);
    expect(fs.existsSync(path.join(outputDir, 'page.html'))).toBe(true);
  });

  it('throws if content directory does not exist', () => {
    expect(() =>
      build({ contentDir: '/nonexistent/content', outputDir }),
    ).toThrow('Content directory not found');
  });

  it('handles empty content directory', () => {
    build({ contentDir, outputDir });

    const indexPath = path.join(outputDir, 'index.html');
    expect(fs.existsSync(indexPath)).toBe(true);
    const html = fs.readFileSync(indexPath, 'utf-8');
    expect(html).toContain('All Pages');
  });
});

